import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {createClient} from "@sanity/client";
import {productGalleryMedia} from "../coffee/lib/product-media.js";
import {buildRfqMessage} from "../coffee/lib/rfq-message.js";
const slug="12oz-stainless-steel-insulated-milk-mug-with-inner-scale";
const client=createClient({projectId:"12npkiv4",dataset:"production",apiVersion:"2026-10-20",useCdn:false,timeout:20000,maxRetries:0});
const p=await client.fetch('*[_type=="coffeeProduct" && slug==$slug][0]',{slug});
assert.equal(p.name,"12oz / 16oz Stainless Steel Insulated Coffee Mug with Inner Scale");
assert.deepEqual(p.variants.map(v=>[v.name,v.size,v.priceUsd]),[["12oz (360ml)","12oz (360ml)",2.58],["16oz (500ml)","16oz (500ml)",3.52]]);
for(const key of ["description","shortDescription","detailText","specificationsText"])for(const size of ["12oz (360ml)","16oz (500ml)"])assert.ok(p[key].includes(size),key+": missing "+size);
for(const heading of ["Weight (12oz)","Dimensions (12oz)","Carton (12oz)"])assert.ok(p.specificationsText.includes(heading));
assert.equal(p.galleryImages.length,15);assert.equal(p.galleryImages[0].imageUrl,p.imageUrl);
const media=productGalleryMedia(p.galleryImages,p.videoUrls,p.videoPosterUrl);assert.equal(media[1].type,"video");
assert.ok(media[6].image.imageUrl.includes("333fb290e34e6ecdcf12ae0c4409431e33a38827"));
const path="/coffee-mug/"+slug;
const html=process.argv[2]?await fetch(process.argv[2]+path+"?release=cm01-large-20261020",{signal:AbortSignal.timeout(20000)}).then(r=>{assert.equal(r.status,200);return r.text();}):readFileSync(new URL("../.next/server/app"+path+".html",import.meta.url),"utf8");
assert.ok(html.includes("16oz<span"));assert.ok(html.includes('text-xs font-normal text-slate-500">(500ml)'));
assert.ok(html.includes("12oz<span"));assert.ok(html.includes('text-xs font-normal text-slate-500">(360ml)'));
assert.ok(html.includes("Available in 12oz (360ml) and 16oz (500ml)"));
assert.equal((html.match(/aria-label="View product image \d+"/g)||[]).length,15);
const labels=[...html.matchAll(/aria-label="(View product image \d+|Play product video)"/g)].map(m=>m[1]);assert.equal(labels[1],"Play product video");
assert.ok(buildRfqMessage({productSlug:slug,selectedOption:"16oz (500ml)",quantity:50},[p]).text.includes("Option: 16oz (500ml)"));
console.log("PASS CM01: 12oz $2.58, 16oz $3.52; 15 images; source media 7 retained; video second; secondary ml; complete inquiry size.");
